"""Cross-build an opaque native C/COM SDK and independent Windows consumers."""
from pathlib import Path
import argparse,hashlib,json,os,subprocess,tempfile
ROOT=Path(__file__).resolve().parents[2]
def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()
def main():
	parser=argparse.ArgumentParser(description=__doc__)
	for name in ['compiler','cc','cxx','sysroot','output']:parser.add_argument('--'+name,type=Path,required=True)
	args=parser.parse_args();compiler=args.compiler.resolve();output=args.output.resolve();assert not output.is_relative_to(ROOT);output.mkdir(parents=True,exist_ok=True);work=Path(tempfile.mkdtemp(prefix='opaque-com-unit-',dir=output));media=work/'media';media.mkdir();here=Path(__file__).resolve().parent;sources=[Path(__file__).resolve(),*[here/('com-unit'+suffix) for suffix in ['.astra','-protocol.astra','-consumer.astra','-client.cpp']],ROOT/'lib/runtime/interop/foreign-14.c'];receipt=dict(scope='opaque /4 native Windows C/COM SDK prerequisite; execution required and final M16 gates separate',compiler_sha256=sha(compiler),sources={str(p.relative_to(ROOT)):sha(p) for p in sources},checks=[],products={},execution_expectations={})
	def run(command):
		assert sha(compiler)==receipt['compiler_sha256'];p=subprocess.run(list(map(str,command)),capture_output=True,text=True,cwd=work,timeout=120,env=dict(os.environ,CCACHE_DISABLE='1',PYTHONDONTWRITEBYTECODE='1'));receipt['checks'].append(dict(command=list(map(str,command)),exit=p.returncode,stdout=p.stdout,stderr=p.stderr));(work/'build.json').write_text(json.dumps(receipt,indent=2)+'\n');assert p.returncode==0,receipt['checks'][-1];return p.stdout
	selected=['--target=x86_64-w64-windows-gnu','--foreign-personalities=c,com'];sysroot=['--sysroot='+str(args.sysroot.resolve())];strict=['-std=c++17','-Wall','-Wextra','-Werror','-pedantic','-fno-exceptions','-fno-rtti'];objdump=run([args.cxx,'-print-prog-name=objdump']).strip();runtime=work/'foreign.o';run([args.cc,*sysroot,'-std=c11','-O2','-c',ROOT/'lib/runtime/interop/foreign-14.c','-o',runtime]);probe=work/'allocation-probe.hpp';probe.write_text('#include <objbase.h>\nextern "C" void opaquecom16_task_free(void *);\n#define CoTaskMemFree opaquecom16_task_free\n')
	for native_level in '012':
		unit=work/('producer-O'+native_level);unit.mkdir();source=unit/'implementation.astra';protocol=unit/'protocol.astra';source.write_bytes((here/'com-unit.astra').read_bytes());protocol.write_bytes((here/'com-unit-protocol.astra').read_bytes());interface=unit/'session.asti';obj=unit/'session.o';run([compiler,*selected,'-O'+native_level,'-c','--module','WinUnit16','--native-export','WinUnit16.Session','--native-export','WinUnit16.Fault','--native-export','WinUnit16.foreign_fault','--emit-interface',interface,source,protocol,'-o',obj]);source.unlink();protocol.unlink();assert 'schema=windows-x64-llp64-foreign-units/4' in interface.read_text() and '[foreign-import IOpaque16]' in interface.read_text();consumer=unit/'consumer.astra';consumer.write_bytes((here/'com-unit-consumer.astra').read_bytes());native=unit/'consumer.o';run([compiler,*selected,'-O'+native_level,'-c','--import-module',interface,consumer,'-o',native]);header=unit/'sdk.hpp';header.write_text(run([compiler,*selected,'--import-module',interface,'--emit-com-header',consumer]));adapter=unit/'adapter.cpp';adapter.write_text(run([compiler,*selected,'--import-module',interface,'--emit-com-source',consumer]));assert not source.exists() and not protocol.exists() and 'reinterpret_cast' not in adapter.read_text();header_probe=unit/'header.cpp';header_probe.write_text('#include "sdk.hpp"\n#include "sdk.hpp"\n');run([args.cxx,*sysroot,*strict,'-fsyntax-only',header_probe])
		for bridge_level in ('1' if native_level=='1' else '02'):
			bridge=unit/('bridge-O'+bridge_level+'.o');run([args.cxx,*sysroot,*strict,'-O'+bridge_level,'-include',probe,'-c',adapter,'-o',bridge]);binary=media/('opaque-com-O'+native_level+'-bridge-O'+bridge_level+'.exe');run([args.cxx,*sysroot,*strict,'-O2','-static','-Wl,--no-insert-timestamp',here/'com-unit-client.cpp',bridge,obj,native,runtime,'-lole32','-luuid','-o',binary]);imports=run([objdump,'-p',binary]);deps=[line.split(':',1)[1].strip().lower() for line in imports.splitlines() if 'DLL Name:' in line];assert deps and set(deps)<={'kernel32.dll','msvcrt.dll','ole32.dll'};receipt['products'][binary.name]=sha(binary);receipt['execution_expectations'][binary.name]=dict(pass_markers=['PASS opaque native COM SDK imports and exports, captured callbacks and exact lifetimes'],system_dlls=deps)
	receipt['status']='CROSS_BUILD_PASS; native Windows execution pending';(work/'build.json').write_text(json.dumps(receipt,indent=2)+'\n');print(work/'build.json')
if __name__=='__main__':main()
